def compare_name_lengths(first_name, last_name):
    len_first, len_last = len(first_name), len(last_name)
    if len_first > len_last:
        longer = "first_name"
    elif len_last > len_first:
        longer = "last_name"
    else:
        longer = "equal"
    return len_first, len_last, longer
